 for(const id of ['network-scope','network-candidates','network-bodies','network-unlinked'])$(id).onchange=()=>{if(lensState&&!networkRecords(data,networkOptions()).some(r=>r.id===lensState.record))closeInteraction();selected=null;build();if(lensState){syncInteractionRecords();inspect('record',lensState.record);}else inspect('overview');status('Network filter updated from the retained source records.');};
